async function loadUnusualHistory() {
  try {
    const raw = await readFile(resolve(DATA_DIR, UNUSUAL_HISTORY_FILE), "utf8");
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

// Same preservation pattern again for the rolling 7-day hit log that powers
