// Truncate a headline title for prompt budget without losing the lead.
function clipHeadlineTitle(t, maxLen = 160) {
  const cleaned = (t || "").replace(/\s+/g, " ").trim();
  return cleaned.length > maxLen ? cleaned.slice(0, maxLen - 1) + "…" : cleaned;
}

// Format one headline as a single SOURCE POOL line. Stable shape the AI
// copies verbatim into a narrative's `sources` array.
function formatPoolLine(scope, publisher, title, publishedAt) {
  const date = publishedAt ? publishedAt.slice(0, 10) : "undated";
  const pub = (publisher || "source").trim();
  return `- ${scope} [${date}] (${pub}) "${clipHeadlineTitle(title)}"`;
}

function buildNarrativeUserMessage(chains, previousNames, macroHeadlines) {
  const lines = Object.entries(chains).map(([sym, data]) => {
    const news = data.news;
    const sentiment = news?.sentiment || "unknown";
    const summary = (news?.paragraph || "").replace(/\s+/g, " ").trim();
    const firstHl = Array.isArray(news?.headlines) && news.headlines.length ? news.headlines[0] : null;
    // headlines used to be plain strings; they're now {title, publisher, …}.
    // Accept either shape so a half-stale data dir doesn't break the build.
    const topHeadlineRaw = !firstHl
      ? ""
      : typeof firstHl === "string"
        ? firstHl
        : (firstHl.title || "");
    const topHeadlinePub = firstHl && typeof firstHl === "object" ? (firstHl.publisher || "") : "";
    const topHeadline = topHeadlineRaw.replace(/\s+/g, " ").trim();
    // Trim each ticker block so the combined prompt stays well under the
    // model's context — Gemma 4 26B has plenty of room but we send ~65 of these.
    const summaryClip = summary.length > 260 ? summary.slice(0, 257) + "…" : summary;
    const headlineClip = topHeadline.length > 140 ? topHeadline.slice(0, 137) + "…" : topHeadline;
    const pubTag = topHeadlinePub ? ` (${topHeadlinePub})` : "";
    return `- ${sym} [${sentiment}] ${summaryClip}` + (headlineClip ? ` Headline${pubTag}: "${headlineClip}"` : "");
  });
  const previousBlock = previousNames.length
    ? `Previous narrative names from the last build (reuse verbatim when the same story is still live):\n${previousNames.map((n) => `- ${n}`).join("\n")}`
    : "No previous narratives recorded.";

  // SOURCE POOL — every cite-able headline the AI is allowed to copy into a
  // narrative's `sources` array. Macro feeds first (already reputable by
  // construction), then up to 2 per-ticker headlines per symbol (also
  // reputable by construction since fetchTickerHeadlines hard-filters).
  // Each line uses the exact same format we ask the AI to echo back —
  // `(publisher) "title"` — so copy-paste lookup is trivial in cleanNarrative.
  const poolMacroLines = Array.isArray(macroHeadlines) && macroHeadlines.length
    ? macroHeadlines.slice(0, MACRO_TOTAL_CAP).map((h) =>
        formatPoolLine("MACRO", h.publisher, h.title, h.publishedAt))
    : [];
  const poolTickerLines = [];
  for (const [sym, data] of Object.entries(chains)) {
    const hs = Array.isArray(data?.news?.headlines) ? data.news.headlines.slice(0, 2) : [];
    for (const h of hs) {
      if (!h || typeof h !== "object") continue;
      if (!h.title || !h.publisher) continue;
      poolTickerLines.push(formatPoolLine(sym, h.publisher, h.title, h.publishedAt));
    }
  }
  const sourcePoolBlock = (poolMacroLines.length || poolTickerLines.length)
    ? `${poolMacroLines.join("\n")}${poolMacroLines.length && poolTickerLines.length ? "\n" : ""}${poolTickerLines.join("\n")}`
    : "(empty source pool — emit empty sources arrays this run)";

  // Legacy macro digest for narrative-trigger context (kept separate from the
  // SOURCE POOL above so the AI understands these are also fair game to cite
  // — same shape, same publishers).
  const macroLines = Array.isArray(macroHeadlines) && macroHeadlines.length
    ? macroHeadlines.slice(0, MACRO_TOTAL_CAP).map((h) => {
        const date = h.publishedAt ? h.publishedAt.slice(0, 10) : "undated";
        const t = (h.title || "").replace(/\s+/g, " ").trim();
        const clipped = t.length > 180 ? t.slice(0, 177) + "…" : t;
        return `- [${date}] (${h.publisher || "source"}) ${clipped}`;
      }).join("\n")
    : "(no macro headlines retrieved)";
  const industryWhitelist = SECTOR_ORDER
    .map((sector) => `  ${sector}:\n` + (INDUSTRIES_BY_SECTOR[sector] || []).map((ind) => `    - ${ind}`).join("\n"))
    .join("\n");
  return (
    `Tickers in scope: ${Object.keys(chains).join(", ")}\n\n` +
    `INDUSTRY WHITELIST — the "industry" field on every narrative must match one of these exact strings:\n${industryWhitelist}\n\n` +
    `${previousBlock}\n\n` +
    `Macro headlines digest (official + major business press, newest first — use these to judge whether each narrative's trigger has fired):\n${macroLines}\n\n` +
    `SOURCE POOL — the ONLY headlines you may cite in any narrative's "sources" array. Copy publisher + title verbatim. Each line is one cite-able headline; macro entries start with "MACRO", ticker-specific entries start with the ticker symbol.\n${sourcePoolBlock}\n\n` +
    `Recent per-ticker news takes:\n${lines.join("\n")}`
  );
}

// Narrative extraction is a single critical call (vs the 65 per-ticker news
// calls where one failure is acceptable), so we retry more aggressively here —
// MORE attempts, not LONGER sleeps. The old schedule's 30/45/60s tail rungs
// burned up to ~3min of pure backoff on the synchronous critical path during a
// Gemini 503 "high demand" storm (and a 503 spike rarely clears inside one
// build anyway). Keep the extra attempts (7 vs the ticker calls' 6) for blip
// tolerance, but cap each wait at ~15s so the worst case is ~75s, not ~3min;
// past that the build degrades gracefully to last-good (stale) narratives.
// (A genuine 429 quota hint still overrides this via effectiveWait = max(...).)
const NARRATIVE_MAX_ATTEMPTS = 7;
const NARRATIVE_RETRY_BACKOFF_MS = [3000, 6000, 10000, 15000, 15000, 15000];

async function generateMarketNarratives(ai, chains, previousNames, macroHeadlines) {
  const userMessage = buildNarrativeUserMessage(chains, previousNames, macroHeadlines);
  let response;
  let lastErr;
  for (let attempt = 0; attempt < NARRATIVE_MAX_ATTEMPTS; attempt++) {
    try {
      await acquireAiSlot();
      response = await ai.models.generateContent({
        model: aiModelForAttempt(NARRATIVES_MODEL, attempt),
        // System prompt goes in config.systemInstruction (NOT inlined into
        // contents) so it forms the implicit-cache key prefix — matching the
        // ticker-judgment / signals / chart calls. @google/genai drops a
        // top-level systemInstruction, so it MUST nest inside config. (Cash
        // savings are ~0 today — the 8 daily builds are an hour apart, past the
        // implicit-cache TTL — but it engages on the in-build retry loop and
        // keeps every call site consistent.)
        contents: userMessage,
        config: {
          systemInstruction: NARRATIVE_SYSTEM_PROMPT,
          temperature: 0.4,
          // Gemini 2.5 Flash counts "thinking" tokens against
          // maxOutputTokens, and on this prompt the dynamic thinking
          // budget was eating ~95% of the old 4200 cap — leaving only a
          // few hundred chars of actual JSON before the response was
          // truncated mid-string (parse failed at byte ~670, well before
          // the first sector even closed). Give the answer plenty of
          // headroom and zero out the thinking budget: the prompt is
          // already explicit about the shape, so deliberation isn't
          // worth losing the response over. Bumped 16384 → 32768 when the
          // schema grew (per-narrative + per-sector bull/base/bear cases, hype
          // read, lifecycleStage, + the per-narrative lifecycleOutlook why/next/
          // trigger) — roughly 3-4× the payload. Prod NARRATIVES_MODEL
          // is Flash (handles 32k fine); a free-tier Gemma fork may still drop
          // some fields, which the parser + renderer tolerate (graceful degrade).
          maxOutputTokens: 32768,
          thinkingConfig: { thinkingBudget: 0 },
          // Constrained-decoder JSON mode — narratives is the call that
          // most reliably hits malformed-JSON failures because its output
          // is the longest and most structured.
          responseMimeType: "application/json",
        },
      });
      recordAiUsage({ model: aiModelForAttempt(NARRATIVES_MODEL, attempt), callType: "narratives", usage: response?.usageMetadata });
      break;
    } catch (err) {
      lastErr = err;
      // Classify with the standard helper but use the narrative-specific
      // backoff schedule when the error is transient.
      const wait = classifyAiError(err, attempt, aiModelForAttempt(NARRATIVES_MODEL, attempt));
      if (wait == null || attempt === NARRATIVE_MAX_ATTEMPTS - 1) throw err;
      const narrativeWait = NARRATIVE_RETRY_BACKOFF_MS[attempt] ?? 15000;
      // Honour the rate-limit hint from classifyAiError when it's larger than
      // our schedule (e.g. a "retry in 30s" hint on attempt 0).
      const effectiveWait = Math.max(wait, narrativeWait);
      const causeMsg = err?.cause?.code || err?.cause?.message || "";
      console.log(
        `    ↻ narrative attempt ${attempt + 1}/${NARRATIVE_MAX_ATTEMPTS} failed (${err.message}` +
        (causeMsg ? ` · cause ${causeMsg}` : "") +
        `) — retrying in ${Math.round(effectiveWait / 1000)}s`,
      );
      await new Promise((r) => setTimeout(r, effectiveWait));
    }
  }
  if (!response) throw lastErr ?? new Error("no response from Gemini");
  const text = response.text;
  if (!text) throw new Error("empty Gemini response");
  const stripped = text.replace(/^```(?:json)?\s*/i, "").replace(/\s*```\s*$/, "").trim();
  const firstBrace = stripped.indexOf("{");
  const lastBrace = stripped.lastIndexOf("}");
  const jsonText = firstBrace >= 0 && lastBrace > firstBrace
    ? stripped.slice(firstBrace, lastBrace + 1)
    : stripped;
  // Wrap JSON.parse so a malformed response surfaces an excerpt of what the
  // model actually wrote — saves a debugging round-trip if the constrained
  // decoder ever fails open. JSON.parse errors otherwise carry only a byte
  // offset, no content.
  let parsed;
  try {
    parsed = JSON.parse(jsonText);
  } catch (parseErr) {
    const excerpt = jsonText.slice(0, 500).replace(/\s+/g, " ");
    // Pull finishReason + token usage when available — a "MAX_TOKENS"
    // finish on a parse failure means we got truncated and need to
    // raise maxOutputTokens / drop the thinking budget further.
    const finishReason = response?.candidates?.[0]?.finishReason || "unknown";
    const usage = response?.usageMetadata || {};
    const usageStr = `prompt=${usage.promptTokenCount ?? "?"} thoughts=${usage.thoughtsTokenCount ?? 0} output=${usage.candidatesTokenCount ?? "?"} total=${usage.totalTokenCount ?? "?"}`;
    console.log(`    ⚠ narrative JSON parse failed (${parseErr.message}) — finishReason=${finishReason} · ${usageStr}. Response excerpt: ${excerpt}`);
    throw parseErr;
  }
  const validSymbols = new Set(Object.keys(chains));
  const sanitizeTickers = (arr) =>
    Array.isArray(arr)
      ? Array.from(new Set(arr
          .map((s) => String(s || "").toUpperCase().trim())
          .filter((s) => validSymbols.has(s))))
      : [];
  const sanitizeStringList = (arr, max, maxLen) =>
    Array.isArray(arr)
      ? Array.from(new Set(arr
          .map((s) => String(s || "").replace(/\s+/g, " ").trim())
          .filter((s) => s.length > 0)
          .map((s) => (s.length > maxLen ? s.slice(0, maxLen - 1) + "…" : s))))
          .slice(0, max)
      : [];
  // Bull/base/bear case: one short sentence, collapsed whitespace, hard-clipped.
  const cleanCase = (s) => String(s || "").replace(/\s+/g, " ").trim().slice(0, 240);
  const VALID_STATUS = ["active", "building", "fading"];
  const VALID_TIMEFRAME = ["immediate", "near-term", "medium-term", "long-term"];
  const VALID_STANCE = ["bullish", "bearish", "mixed"];
  const STATUS_WEIGHT = { active: 2, building: 1, fading: 0 };
  const TF_WEIGHT = { immediate: 3, "near-term": 2, "medium-term": 1, "long-term": 0 };

  // Build a lookup of every cite-able headline the AI was actually given,
  // keyed by lowercased+trimmed "publisher|title" (with the same title clip
  // applied at prompt time so the keys line up exactly). The AI is allowed
  // to copy entries verbatim; anything that doesn't match a real headline
  // is hallucinated and gets dropped in cleanNarrative below.
  const sourceKey = (pub, title) =>
    `${String(pub || "").toLowerCase().trim()}|${clipHeadlineTitle(title).toLowerCase()}`;
  const validSourcesPool = new Map();
  if (Array.isArray(macroHeadlines)) {
    for (const h of macroHeadlines.slice(0, MACRO_TOTAL_CAP)) {
      if (!h?.title || !h?.publisher) continue;
      validSourcesPool.set(sourceKey(h.publisher, h.title), {
        publisher: h.publisher,
        title: clipHeadlineTitle(h.title),
        date: h.publishedAt ? h.publishedAt.slice(0, 10) : null,
      });
    }
  }
  for (const [, data] of Object.entries(chains)) {
    const hs = Array.isArray(data?.news?.headlines) ? data.news.headlines.slice(0, 2) : [];
    for (const h of hs) {
      if (!h || typeof h !== "object" || !h.title || !h.publisher) continue;
      validSourcesPool.set(sourceKey(h.publisher, h.title), {
        publisher: h.publisher,
        title: clipHeadlineTitle(h.title),
        date: h.publishedAt ? h.publishedAt.slice(0, 10) : null,
      });
    }
  }
  const sanitizeSources = (arr) => {
    if (!Array.isArray(arr)) return [];
    const out = [];
    const seen = new Set();
    for (const raw of arr) {
      if (!raw || typeof raw !== "object") continue;
      const pub = String(raw.publisher || "").trim();
      const title = String(raw.title || "").trim();
      if (!pub || !title) continue;
      const key = sourceKey(pub, title);
      if (seen.has(key)) continue;
      const hit = validSourcesPool.get(key);
      if (!hit) continue; // dropped — AI cited a headline that wasn't in the pool
      seen.add(key);
      out.push({ publisher: hit.publisher, title: hit.title, date: hit.date });
      if (out.length >= 4) break;
    }
    // Newest first; entries without a date sort last.
    out.sort((a, b) => (b.date || "").localeCompare(a.date || ""));
    return out;
  };

  // The new prompt emits a sectors[] array; tolerate the legacy flat
  // narratives[] shape for stale-fallback safety.
  const sectorsRaw = Array.isArray(parsed.sectors) ? parsed.sectors : null;
  const legacyNarrativesRaw = Array.isArray(parsed.narratives) ? parsed.narratives : null;

  const cleanNarrative = (n, sectorHint) => {
    const name = String(n.name || "").trim();
    const thesis = String(n.thesis || "").trim();
    const sentiment = n.sentiment === "bearish" ? "bearish" : "bullish";
    const confidence = ["high", "medium", "low"].includes(n.confidence) ? n.confidence : "medium";
    const longs = sanitizeTickers(n.longs);
    const shorts = sanitizeTickers(n.shorts);
    let strength = Number(n.strength);
    if (!isFinite(strength)) strength = confidence === "high" ? 70 : confidence === "low" ? 30 : 50;
    strength = Math.max(0, Math.min(100, Math.round(strength)));
    const status = VALID_STATUS.includes(n.status) ? n.status : "active";
    const timeframe = VALID_TIMEFRAME.includes(n.timeframe) ? n.timeframe : "near-term";
    // Where this story sits in the 6-stage boom→bust arc; defaults off status.
    const lifecycleStage = normalizeLifecycleStage(n.lifecycleStage, status);
    // Forward read on the arc: WHY it sits at this stage, what stage comes NEXT,
    // and the trigger (with rough timing) that would confirm the transition.
    const lifecycleOutlook = cleanLifecycleOutlook(n.lifecycleOutlook, lifecycleStage, cleanCase);
    // The three scenario paths + the fundamentals-vs-hype read (six-question framework).
    const bullCase = cleanCase(n.bullCase);
    const baseCase = cleanCase(n.baseCase);
    const bearCase = cleanCase(n.bearCase);
    const hype = normalizeHype(n.hype);
    // watchFor is the new field; accept legacy `triggers` from older snapshots.
    const watchFor = sanitizeStringList(
      Array.isArray(n.watchFor) ? n.watchFor : n.triggers,
      3,
      160,
    );
    const conflictsWithRaw = sanitizeStringList(n.conflictsWith, 4, 60);
    const sources = sanitizeSources(n.sources);
    // Industry must match the whitelist. If the model omits / invents one,
    // vote from the longs (then shorts). Falls back to "Uncategorized" only
    // when no ticker resolves either (which the upstream filter then drops).
    const industry = resolveNarrativeIndustry(n.industry, longs, shorts);
    const out = { name, industry, thesis, sentiment, confidence, strength, status, timeframe, lifecycleStage, lifecycleOutlook, bullCase, baseCase, bearCase, hype, watchFor, conflictsWith: conflictsWithRaw, longs, shorts, sources };
    // Stamp the parent sector when we know it from the wrapper. The UI
    // groups by SECTOR_OF_INDUSTRY anyway, but having `sector` on the
    // narrative simplifies the stale-fallback path.
    if (sectorHint) out.sector = sectorHint;
    return out;
  };

  const cleanedNarratives = [];
  const sectorOverviews = {};

  if (sectorsRaw) {
    for (const sec of sectorsRaw) {
      const sectorName = String(sec?.sector || "").trim();
      if (!SECTOR_ORDER.includes(sectorName)) continue;
      const ov = sec.overview || {};
      const ovThesis = String(ov.thesis || "").trim();
      const ovWatchFor = sanitizeStringList(ov.watchFor, 4, 180);
      // stance + strength are NO LONGER trusted from the model — they're computed
      // downstream as the two-level average of this sector's industry-group grades
      // (computeSectorGrades, overlaid below). The AI keeps the qualitative fields:
      // thesis ("dominant narrative"), watchFor ("what would shift it"), the three
      // scenario cases, and the fundamentals-vs-hype read.
      if (ovThesis) {
        sectorOverviews[sectorName] = {
          thesis: ovThesis,
          watchFor: ovWatchFor,
          bullCase: cleanCase(ov.bullCase),
          baseCase: cleanCase(ov.baseCase),
          bearCase: cleanCase(ov.bearCase),
          hype: normalizeHype(ov.hype),
        };
      }
      const subs = Array.isArray(sec.narratives) ? sec.narratives : [];
      for (const n of subs) cleanedNarratives.push(cleanNarrative(n, sectorName));
    }
  } else if (legacyNarrativesRaw) {
    for (const n of legacyNarrativesRaw) cleanedNarratives.push(cleanNarrative(n, null));
  }

  const cleaned = cleanedNarratives
    .filter((n) => n.name && n.thesis && (n.longs.length > 0 || n.shorts.length > 0))
    .slice(0, NARRATIVE_MAX_COUNT);

  // Drop conflictsWith references to names that aren't in our final cleaned
  // set — the model occasionally hallucinates a conflict against a narrative
  // it didn't actually emit.
  const nameSet = new Map(cleaned.map((n) => [n.name.toLowerCase(), n.name]));
  for (const n of cleaned) {
    n.conflictsWith = n.conflictsWith
      .map((c) => nameSet.get(c.toLowerCase()))
      .filter((c) => c && c.toLowerCase() !== n.name.toLowerCase());
  }
  // Sort strongest-first regardless of the order the model returned them in:
  // strength desc, then active > building > fading, then immediate > long-term,
  // then confidence high > medium > low as a stable tiebreaker.
  const CONF_WEIGHT = { high: 2, medium: 1, low: 0 };
  cleaned.sort((a, b) => {
    if (b.strength !== a.strength) return b.strength - a.strength;
    const sw = (STATUS_WEIGHT[b.status] || 0) - (STATUS_WEIGHT[a.status] || 0);
    if (sw !== 0) return sw;
    const tw = (TF_WEIGHT[b.timeframe] || 0) - (TF_WEIGHT[a.timeframe] || 0);
    if (tw !== 0) return tw;
    return (CONF_WEIGHT[b.confidence] || 0) - (CONF_WEIGHT[a.confidence] || 0);
  });
  // Fill in sub-industry watchlists for any curated ticker the AI didn't
  // mention. Appended AFTER the slice + sort so the synthetic cards always
  // sit at the bottom of their industry section without crowding out real
  // narratives at the cap.
  // Two-level rollup: a sector's stance/strength is the average of its
  // industry-group grades (each the signed-strength average of its narratives).
  // Computed on `cleaned` (real narratives only — autogenerated watchlist filler
  // is excluded inside computeSectorGrades) and overlaid onto the prose overviews
  // built above. A graded sector the model skipped a thesis for still gets a bare
  // overview so its grade banner renders; a thin/empty sector reads mixed / 0.
  const sectorGrades = computeSectorGrades(cleaned);
  for (const sector of SECTOR_ORDER) {
    const grade = sectorGrades[sector];
    const existing = sectorOverviews[sector];
    if (!grade && !existing) continue;
    sectorOverviews[sector] = {
      ...(existing || {}),
      stance: grade ? grade.stance : "mixed",
      strength: grade ? grade.strength : 0,
      score: grade ? grade.score : 0,
      lifecycleStage: grade ? grade.lifecycleStage : null,
      lifecycleOutlook: grade ? grade.lifecycleOutlook : null,
      industryGrades: grade ? grade.industryGrades : [],
    };
  }

  const covered = ensureTickerCoverage(cleaned, validSymbols);
  return { narratives: covered, sectorOverviews };
}

// Walk back through prior snapshots to discover when each narrative first
// appeared (matched by case-insensitive name). Gives the UI a "running for N
// days" badge so the user can see which stories are fresh vs. entrenched.
function annotateNarrativesWithLifespan(narratives, history, todayIso) {
  const today = todayIso.slice(0, 10);
  return narratives.map((n) => {
    const lcName = n.name.toLowerCase();
    let firstSeen = today;
    // History is newest-first below; iterate to find the OLDEST contiguous
    // run that includes this narrative.
    for (let i = 0; i < history.length; i++) {
      const snap = history[i];
      const hit = (snap.narratives || []).find((h) => h && h.name && h.name.toLowerCase() === lcName);
      if (hit) {
        firstSeen = snap.date;
      } else {
        // First gap breaks the streak — the lifespan is the contiguous run.
        break;
      }
    }
    const daysRunning =
      Math.max(1, Math.floor((new Date(today + "T00:00:00Z").getTime() - new Date(firstSeen + "T00:00:00Z").getTime()) / 86400000) + 1);
    return { ...n, firstSeen, daysRunning };
  });
}

function updateTrendHistory(history, narratives, todayIso) {
  const date = todayIso.slice(0, 10);
  // Compact snapshot — name + sentiment + ticker lists are enough to compute
  // continuity and a "trends that came and went" view. Include strength /
  // status so later builds can chart how a narrative built up or faded
  // without bloating the file with theses/triggers. Sources are stored as
  // bare publisher names (deduped) for a 90-day trail of which outlets
  // backed each narrative — the full {publisher, title, date} payload
  // lives in trends.json proper.
  const snapshot = {
    date,
    builtAtIso: todayIso,
    narratives: narratives.map((n) => ({
      name: n.name,
      sentiment: n.sentiment,
      strength: n.strength,
      status: n.status,
      lifecycleStage: n.lifecycleStage,
      longs: n.longs,
      shorts: n.shorts,
      // Carry the coverage-filler discriminator so computeRecentlyEnded can
      // tell real extracted narratives from autogenerated "<Industry>
      // Watchlist" placeholders — a Watchlist vanishing when a real
      // narrative starts covering its orphan tickers is not a trend that
      // "ended". (Legacy snapshots lack this key → falsy → unchanged.)
      autogenerated: !!n.autogenerated,
      sourcePublishers: Array.isArray(n.sources)
        ? Array.from(new Set(n.sources.map((s) => s.publisher).filter(Boolean))).slice(0, 6)
        : [],
    })),
  };
  // Replace any existing snapshot for today (a re-run on the same day overwrites).
  const withoutToday = history.filter((s) => s.date !== date);
  const next = [snapshot, ...withoutToday];
  // Prune anything older than NARRATIVE_HISTORY_DAYS.
  const cutoff = new Date(date + "T00:00:00Z").getTime() - NARRATIVE_HISTORY_DAYS * 86400000;
  return next.filter((s) => new Date(s.date + "T00:00:00Z").getTime() >= cutoff);
}

// Surface narratives that were active in recent history but dropped out today
// — that's the "trends come and go" view. Returns names with their last-seen
// date and total days they ran.
function computeRecentlyEnded(history, activeNarrativeNames, todayIso) {
  const active = new Set(activeNarrativeNames.map((n) => n.toLowerCase()));
  const today = todayIso.slice(0, 10);
  // Build {name -> {firstSeen, lastSeen}} from the (newest-first) history,
  // excluding any that are still active today.
  const seen = new Map();
  for (const snap of history) {
    if (snap.date === today) continue;
    for (const n of (snap.narratives || [])) {
      if (!n || !n.name) continue;
      // Skip autogenerated coverage filler — a "<Industry> Watchlist"
      // placeholder is not a real trend, so its disappearance must not show
      // up in the "recently ended" view as a phantom trend.
      if (n.autogenerated) continue;
      const key = n.name.toLowerCase();
      if (active.has(key)) continue;
      const cur = seen.get(key);
      if (!cur) {
        seen.set(key, { name: n.name, firstSeen: snap.date, lastSeen: snap.date });
      } else {
        if (snap.date < cur.firstSeen) cur.firstSeen = snap.date;
        if (snap.date > cur.lastSeen) cur.lastSeen = snap.date;
      }
    }
  }
  const todayMs = new Date(today + "T00:00:00Z").getTime();
  return Array.from(seen.values())
    .map((e) => ({
      name: e.name,
      lastSeen: e.lastSeen,
      daysSince: Math.max(1, Math.floor((todayMs - new Date(e.lastSeen + "T00:00:00Z").getTime()) / 86400000)),
      ranDays: Math.max(1, Math.floor((new Date(e.lastSeen + "T00:00:00Z").getTime() - new Date(e.firstSeen + "T00:00:00Z").getTime()) / 86400000) + 1),
    }))
    .sort((a, b) => a.daysSince - b.daysSince)
    .slice(0, 8);
}

async function attachMarketNarratives(chains, previousHistory, macroReleaseReads = []) {
  if (!process.env.GEMINI_API_KEY) {
    console.log("No GEMINI_API_KEY set — skipping market narrative extraction.");
    // The headline slate is pure RSS (no key needed) and feeds the macro
    // regime's headline-tone axis — fetch it anyway so a keyless bake doesn't
    // persist [] into trends.json and silently disable that axis (plus the
    // briefs' and regen-picks' committed-slate fallbacks).
    let keylessHeadlines = [];
    try { keylessHeadlines = await fetchMacroHeadlines(); } catch (_) { /* degrade to empty */ }
    return { narratives: [], sectorOverviews: {}, recentlyEnded: [], history: previousHistory, macroHeadlines: keylessHeadlines };
  }
  const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });
  const lastSnapshot = previousHistory[0];
  // Guard the inner .narratives/.name access (not just lastSnapshot): this runs
  // before the stale-fallback try/catch below, so a malformed or legacy history
  // snapshot lacking a narratives array would otherwise throw and abort the
  // whole bake. Mirrors the guards in annotateNarrativesWithLifespan.
  const previousNames = Array.isArray(lastSnapshot?.narratives)
    ? lastSnapshot.narratives.map((n) => n?.name).filter(Boolean)
    : [];
  // Macro RSS fetch — independent of the AI rate limiter, runs concurrently
  // with anything the limiter still has queued. The narrative generateContent
  // call will block on acquireAiSlot() if the previous pass's window hasn't
  // fully cleared yet, so we no longer need an explicit pass cooldown here.
  console.log(`Fetching macro headlines across ${MACRO_FEEDS.length} feeds…`);
  const macroHeadlines = await fetchMacroHeadlines();
  console.log(`  · ${macroHeadlines.length} macro headlines retrieved`);
  // Same-day macro prints (CPI/PPI/jobs actual vs consensus, classified by
  // buildMacroReleaseReads) lead the digest as structured pseudo-headlines —
  // the RSS feeds only carry release TITLES, so without this the model is
  // asked to judge "did the hot-CPI trigger fire?" without ever seeing the
  // number. Prompt-only: the returned macroHeadlines stay RSS-only so
  // calendar.json's headline events don't duplicate its report rows.
  const releaseItems = (Array.isArray(macroReleaseReads) ? macroReleaseReads : []).map((r) => ({
    publisher: "BLS data",
    source: "BLS data",
    title: r.line,
    publishedAt: r.date + "T13:30:00Z",
  }));
  if (releaseItems.length) console.log(`  · ${releaseItems.length} same-day macro print(s) added to the digest`);
  const headlinesForPrompt = releaseItems.concat(macroHeadlines);
  console.log(`Extracting market narratives across ${Object.keys(chains).length} tickers…`);
  try {
    const raw = await generateMarketNarratives(ai, chains, previousNames, headlinesForPrompt);
    const builtAtIso = new Date().toISOString();
    const narratives = annotateNarrativesWithLifespan(raw.narratives, previousHistory, builtAtIso);
    const history = updateTrendHistory(previousHistory, narratives, builtAtIso);
    const recentlyEnded = computeRecentlyEnded(history, narratives.map((n) => n.name), builtAtIso);
    const sectorOverviews = raw.sectorOverviews || {};
    console.log(`  ✓ ${narratives.length} narratives extracted across ${Object.keys(sectorOverviews).length} sectors (ordered strongest → weakest)`);
    for (const sec of SECTOR_ORDER) {
      const ov = sectorOverviews[sec];
      if (ov) {
        console.log(`    [${sec}] ${ov.stance.toUpperCase()} · str ${ov.strength} · watchFor=${ov.watchFor.length}`);
      }
    }
    for (const n of narratives) {
      console.log(`    · ${n.name} [str ${n.strength}, ${n.status}, ${n.timeframe}, ${n.sentiment}, conf ${n.confidence}, day ${n.daysRunning}] long=${n.longs.join(",")||"—"} short=${n.shorts.join(",")||"—"}` +
        (n.conflictsWith.length ? ` ⚔ ${n.conflictsWith.join(" | ")}` : ""));
    }
    return { narratives, sectorOverviews, recentlyEnded, history, macroHeadlines };
  } catch (err) {
    const causeMsg = err?.cause?.code || err?.cause?.message || "";
    console.log(
      `  ✗ Narrative extraction failed after retries: ${err.message}` +
      (causeMsg ? ` · cause ${causeMsg}` : ""),
    );
    // Fall back to the last good narratives so the page never shows an empty
    // card from a transient outage. We mark them stale (with staleSinceIso
    // preserved across consecutive failures so the staleness age is honest)
    // and persist them back to trends.json — that way a SECOND failure can
    // still recover them. The history file is intentionally left unchanged:
    // history records what was extracted, not what was displayed.
    const lastGood = await loadLastGoodTrends();
    const lastNarratives = lastGood && Array.isArray(lastGood.narratives) ? lastGood.narratives : [];
    const lastSectorOverviews = lastGood && lastGood.sectorOverviews && typeof lastGood.sectorOverviews === "object"
      ? lastGood.sectorOverviews
      : {};
    if (lastNarratives.length) {
      const todayIso = new Date().toISOString();
      console.log(`  ↩ falling back to ${lastNarratives.length} narratives from last good build (${lastGood.builtAtIso || "unknown"})`);
      const staleNarratives = lastNarratives.map((n) => ({
        ...n,
        stale: true,
        staleSinceIso: n.staleSinceIso || todayIso,
      }));
      // Mark stale on sector overviews too so the banner can signal it.
      const staleOverviews = {};
      for (const k of Object.keys(lastSectorOverviews)) {
        const ov = lastSectorOverviews[k];
        staleOverviews[k] = {
          ...ov,
          stale: true,
          staleSinceIso: ov.staleSinceIso || todayIso,
        };
      }
      return {
        narratives: staleNarratives,
        sectorOverviews: staleOverviews,
        recentlyEnded: Array.isArray(lastGood.recentlyEnded) ? lastGood.recentlyEnded : [],
        history: previousHistory,
        macroHeadlines,
      };
    }
    return { narratives: [], sectorOverviews: {}, recentlyEnded: [], history: previousHistory, macroHeadlines };
  }
}

async function main() {
  // Load running AI-usage totals BEFORE the data/ wipe further down so we
  // can merge today's calls into the existing rolling window. Lives in
  // data/ai-usage.json — gets rewritten after writeChainFiles below.
  await loadAiUsageState();
  console.log("Loading SEC CIK mapping…");
  await fetchCikMap();
  console.log("Fetching option chains for", TICKERS.length, "tickers…");
  const chains = await fetchAllTickerChains();
  const got = Object.keys(chains).length;
  const rate = got / TICKERS.length;
  console.log(`Got ${got} / ${TICKERS.length} tickers (${(rate * 100).toFixed(0)}%).`);
  if (rate < MIN_SUCCESS_RATE) {
    throw new Error(
      `Only ${got} / ${TICKERS.length} tickers fetched (need ≥${Math.ceil(MIN_SUCCESS_RATE * TICKERS.length)}). ` +
      `Leaving last-good index.html + data/ in place — GH Pages will keep serving the previous build.`
    );
  }
  // Fetch the macro backdrop (10Y yield + DXY) BEFORE per-ticker AI judgments
  // so the fallback paragraph (used when a ticker has no readable articles)
  // can quote live macro values instead of returning an empty take.
  console.log("Fetching macro backdrop (yields + DXY + VIX)…");
  const macroBackdrop = await fetchMacroBackdrop();
  // CPI + unemployment (monthly BLS/FRED) join the backdrop — surfaced on the
  // Bonds & USD tab and feeding computeMacroRegime's inflation/labor axis.
  // Persisted with the rest of macro.json, so regen-picks sees them too.
  if (macroBackdrop) {
    const il = await fetchInflationLabor();
    if (il.inflation) macroBackdrop.inflation = il.inflation;
    if (il.unemployment) macroBackdrop.unemployment = il.unemployment;
  }
  // Read the rolling macro history BEFORE writeChainFiles wipes data/. The
  // 17:00 ET daily slot is the authoritative end-of-day close — at that
  // capture we overwrite today's entry with the EOD print and the prior-day
  // entry is yesterday's EOD close, giving us a clean day-over-day delta
  // even if Yahoo's intraday `prior1d` lookup flakes.
  const macroHistoryPrev = await readMacroHistory();
  let macroHistoryNext = macroHistoryPrev;
  if (macroBackdrop) {
    const { history, previousClose } = upsertMacroHistory(macroHistoryPrev, macroBackdrop);
    macroHistoryNext = history;
    // Attach the VIX percentile rank (computed off the just-upserted 90-day
    // history) onto the baked leg so the Bonds & USD tile + Execute-now card
    // can show "Nth pct over 90d" without inlining the whole series.
    if (macroBackdrop.vix && macroBackdrop.vix.value != null) {
      const rank = computeVixRank(macroHistoryNext, macroBackdrop.vix.value);
      if (rank) {
        macroBackdrop.vix.rankPct = rank.rankPct;
        macroBackdrop.vix.rankSamples = rank.samples;
      }
    }
    if (previousClose) {
      macroBackdrop.previousClose = previousClose;
      console.log(`Macro prev close (${previousClose.date}): ${
        ["twoY","tenY","thirtyY","dxy","vix"].map((k) => previousClose[k] != null ? `${k}=${previousClose[k]}` : null).filter(Boolean).join(", ")
      }`);
    }
  }
  // Overnight foreign-market sweep (Korea / Japan / Taiwan / China / Europe +
  // FX + US futures) for the correlations engine. Non-fatal: a flaky Yahoo here
  // just leaves data/correlations.json on its last-good snapshot.
  console.log("Fetching global overnight markets…");
  let globalMarkets = {};
  try {
    globalMarkets = await fetchAllGlobalMarkets();
    console.log(`Got ${Object.keys(globalMarkets).length} / ${Object.keys(GLOBAL_MARKETS).length} global markets.`);
  } catch (err) {
    console.log(`Global markets sweep failed: ${err.message}`);
  }
  // Cross-build ticker-judgment cache: read BEFORE writeChainFiles wipes data/
  // (persisted after the wipe, next to the chart-pattern cache). Only the
  // combined path caches — the legacy split path (AI_COMBINED=0) carries the
  // prior map forward untouched so a temporary flag flip doesn't clear it.
  const tickerJudgmentCachePrev = await readTickerJudgmentCache();
  let tickerJudgmentCacheNext = tickerJudgmentCachePrev;
  if (AI_COMBINED) {
    tickerJudgmentCacheNext = await attachTickerJudgments(chains, macroBackdrop, tickerJudgmentCachePrev);
  } else {
    await attachAiNewsTakes(chains, macroBackdrop);
    // No explicit cooldown — acquireAiSlot() is shared across passes, so the
    // first fundamentals request will naturally wait for the news-takes
    // window to drain. Same for the narrative pass that runs next.
    await attachFundamentalsJudgments(chains);
  }
  await attachSocialSentiment(chains);
  // Extract the Major Contract + Guidance fundamentals signals from the news
  // headlines just attached. Mutates chains[sym].aiSignals in memory; consumed
  // later by buildTopPicks → scoreFundamentals. Self-skips without an API key.
  // When AI_SIGNALS_COMBINED is on (and the combined path ran), these signals
  // already came back inside attachTickerJudgments' single per-ticker call, so
  // skip the dedicated round-trip — that is the cost saving. The split path
  // (AI_COMBINED=0) and the flag-off default still use this dedicated pass.
  if (!(AI_COMBINED && AI_SIGNALS_COMBINED)) {
    // Pass the judgment cache so unchanged-headlines names reuse the prior
    // build's extraction (fresh results are stored back onto its entries).
    // The split path (AI_COMBINED=0) has no current-build entries to match,
    // so it calls every name exactly as before.
    await attachAiContractGuidance(chains, AI_COMBINED ? tickerJudgmentCacheNext : null);
  }
  // Identify a classic chart pattern per ticker from the in-memory daily bars.
  // MUST run before writeChainFiles strips _bars (and wipes data/), and before
  // buildTopPicks / buildGradesIndex score scoreTechnicals — the result lands on
  // chains[sym].technicals.chartPattern, persisted into each data/<SYM>.json and
  // read by the Chart Pattern signal. Self-skips without GEMINI_API_KEY.
  // Read the cross-build cache BEFORE writeChainFiles wipes data/; the refreshed
  // map is written back AFTER the wipe (writeChartPatternCache below).
  const chartPatternCachePrev = await readChartPatternCache();
  const chartPatternCacheNext = await attachChartPatterns(chains, chartPatternCachePrev);
  // Thesis-prose cache: read BEFORE writeChainFiles wipes data/ (persisted after
  // the picks file is written below). Carries the AI gloss across builds so it
  // only re-calls when a pick's thesis composition changes.
  const thesisProseCachePrev = await readPickThesisCache();
  // Read trend history + the latest unusual-flow scan BEFORE writeChainFiles
  // wipes data/. Narrative extraction references yesterday's names for
  // continuity; the unusual snapshot is rewritten after the wipe so the page
  // keeps showing it until the next hourly cron runs.
  const previousHistory = await loadTrendHistory();
  const unusual = await loadUnusualFlow();
  const unusualHistory = await loadUnusualHistory();
  const unusualLog = await loadUnusualLog();
  const volumeFlags = await loadVolumeFlags();
  const volumeHistory = await loadVolumeHistory();
  const oiTracker = await loadOiTracker();
  const oiHistory = await loadOiHistory();
  // Fear & Greed history + last-good snapshot live in data/, which
  // writeChainFiles wipes. Load both now and rewrite after the wipe so
  // we keep prior days even if today's CNN fetch fails.
  const fngHistoryPrev = await readFearGreedHistory();
  const fngLastGood = await readLastFearGreed();
  console.log("Fetching CNN Fear & Greed index…");
  const fngFresh = await fetchCnnFearGreed();
  let fearGreed = null;
  if (fngFresh) {
    fearGreed = fngFresh;
    console.log(`  · score=${fngFresh.score} (${fngFresh.rating})`);
  } else if (fngLastGood) {
    fearGreed = { ...fngLastGood, stale: true };
    console.log("  · CNN fetch failed — keeping last-good snapshot (stale).");
  } else {
    console.log("  · CNN fetch failed and no prior snapshot on disk.");
  }
  // collectIvHistory reads each ticker's previous iv-history file from
  // data/iv-history/ before writeChainFiles wipes the directory, then
  // returns an in-memory map to flush back after the wipe.
  const ivHistory = await collectIvHistory(chains);
  // P1.6 — attach IV percentiles onto chains (reads the prior iv-history on disk,
  // ≤1-day lag) BEFORE the wipe, so scoring/computeEntryTiming + the picks card see
  // each name's real implied-vol rank. Mutates chains in-memory; survives the wipe.
  await attachIvRanks(chains);
  // Earnings history — same read-before-wipe contract. The update pass needs
  // chains (live IV + straddle for the upcoming print, _bars for reactions)
  // and the just-collected ivHistory map (pre/post-print IV fills); the
  // refreshed store is written back after the wipe, and attachEarningsHx puts
  // the browser-facing slice on each ticker before writeChainFiles persists it.
  const earningsHxStore = await readEarningsEventsHistory();
  try {
    await updateEarningsEventsHistory(earningsHxStore, chains, ivHistory);
  } catch (err) {
    console.log(`Earnings-history update failed (keeping prior store): ${err.message}`);
  }
  attachEarningsHx(chains, earningsHxStore);
  // Same pattern for the heatmap's EOD recap — generated by the hourly
  // refresh script and stored in data/heatmap.json. Snapshot it before
  // writeChainFiles wipes data/, then thread it back into writeHeatmapFile.
  const priorHeatmapEod = await readPriorHeatmapEodSummary();
  // Rolling sector-rotation breadth snapshots — same pre-wipe read so the bake
  // carries them forward (and records today's close after the bell).
  const priorHeatmapRotation = await readPriorHeatmapSectorRotation();
  // Prior correlations snapshot — fall back to it if tonight's foreign sweep
  // came back too thin (graceful degradation; data/ is about to be wiped).
  const priorCorrelations = await readPriorCorrelations();
  // Prior AI-CapEx + capital-raises snapshots — both are SEC/news-sourced and
  // change slowly (quarterly filings / sparse issuance news), so carry the
  // last-good forward if a build's SEC fetch fails or no fresh issuance news
  // landed. Read before the wipe like the other cross-build artifacts.
  const priorAiCapex = await readPriorAiCapex();
  const priorCapitalRaises = await readPriorCapitalRaises();
  // Prior RAM-prices snapshot — the wholesale-spot side accumulates its own
  // daily history across builds (the sources only publish the current
  // session), so it must be pre-read before the wipe like the other histories.
  const priorRamPrices = await readPriorRamPrices();
  // Load persisted last-good readings BEFORE writeChainFiles wipes data/.
  // Without these reads the caches would never serve a value across builds
  // — the file is gone by the time the post-wipe code tries to read it.
  // We then thread the cached value into fetchRiskFreeRate (so a Yahoo
  // ^IRX flake falls back to the last reading instead of the hardcoded
  // 4.5%) and into the FedWatch block (so a FRED:DFF outage falls back
  // to the last persisted Fed funds rate). The cached payloads are also
  // re-persisted after the wipe so the chain continues.
  const cachedRfr = await readRfrHistory();
  const fedwatchHistoryPrev = await readFedwatchHistory();
  // Prediction-market odds history (Kalshi/Polymarket FOMC trend) — same
  // read-before-wipe rule as fedwatch-history: snapshot it now, append + write
  // after writeChainFiles recreates data/, or the trend resets every build.
  const predictionHistoryPrev = await readPredictionHistory();
  // Pick-accuracy track record: snapshot the persisted tracker BEFORE
  // writeChainFiles wipes data/, then thread it into updatePicksAccuracyFile
  // after the wipe. The file lives in data/, so without this pre-read the
  // post-wipe read always misses and the track record resets to empty every
  // build — open picks never carry forward (so nothing is ever marked to
  // market, timed out, or resolved) and closed stays 0. Same pattern as the
  // macro / iv / fedwatch histories above.
  const picksAccuracyPrev = await readPicksAccuracyState();
  // Snapshot the prior picks.json the same way, BEFORE writeChainFiles wipes
  // data/. Threaded into writeTopPicksFile so the consecutive-build tenure
  // counts survive the wipe and the zero-pick (pre-bell) stale-reuse path can
  // actually find last-good picks instead of overwriting them with [].
  const picksPrev = await readPriorPicks();
  // Same pre-read-before-wipe rule for the grade-change log: data/grades-history.json
  // lives in data/, so snapshot it now and thread it into diffGradesHistory after
  // the wipe, or the change log resets every build.
  const gradesHistoryPrev = await readGradesHistory();
  // Same rule for the daily grade snapshots (data/grades-daily.json) — the
  // universe-IC substrate accumulates across builds, so it must be pre-read
  // before the wipe or the time series resets every build.
  const gradesDailyPrev = await readGradesDaily();
  // Same rule for the daily market-regime timeline (data/regime-history.json) —
  // the Top Picks "risk-on / risk-off history" calendar accumulates across builds,
  // so it must be pre-read before the wipe or the timeline resets every build.
  const regimeHistoryPrev = await readRegimeHistory();
  // Same rule for the daily index-close calendar (data/index-calendar.json) — the
  // SPY/QQQ/IWM red/green + %change history accumulates across builds, so pre-read
  // it before the wipe or the calendar resets every build. (The bars it reads from
  // chains[]._bars survive the wipe, so the append + write happen after it below.)
  const indexCalendarPrev = await readIndexCalendar();
  // Same rule for the picks churn log (data/picks-changes.json) — read it now so
  // this build's entered/exited events append to the rolling log instead of
  // resetting it after the wipe.
  const picksChangesPrev = await readPicksChanges();
  // Same rule for the calendar macro-report salvage: writeCalendarFile's
  // last-good fallback (carry in-window report rows when FRED + BLS both come
  // back empty) reads data/calendar.json, but it runs AFTER writeChainFiles
  // wipes data/ — so without this pre-read the salvage silently never fires and
  // a FRED/BLS outage ships a blank macro calendar. Threaded in via extras.priorCalendar.
  const priorCalendar = await readPriorCalendar();
  // Prior market brief (rolling hourly digest) — read BEFORE writeChainFiles
  // wipes data/, so the brief is minted once per ET hour and carried forward
  // by a same-hour re-run. Threaded into buildMarketBriefs near the end of main().
  const briefsPrev = await readPriorBriefs();
  const riskFreeRate = await fetchRiskFreeRate(cachedRfr);
  // Kick off 13F enrichment (SEC EDGAR per-firm holdings + OpenFIGI CUSIP map)
  // NOW so its ~60-80s runs CONCURRENTLY with the narratives + calendar + scoring
  // phases below, instead of serially after them — it was the build's second
  // biggest stage and is fully off the critical path once overlapped.
  // buildPerFirm13FHoldings() takes no args and reads only the network (never
  // data/, chains, or narratives), so starting it here is safe; the result is
  // awaited far below where the 13F files are written.
  // SEC-safety: the only per-ticker SEC (data.sec.gov) work — fetchRevenueSegments
  // inside fetchAllTickerChains — already finished (chains were awaited above), so
  // this 13F SEC burst is temporally DISJOINT from the per-ticker XBRL burst and
  // does NOT raise the aggregate SEC request rate. Do NOT move this earlier (ahead
  // of the chain fetch) — that WOULD double SEC load and risk an EDGAR IP-block.
  // The 240s timeout starts here (true budget-from-start, now overlapping useful
  // work); clearTimeout fires at the await site when the work resolves first.
  console.log("Fetching per-firm 13F holdings (SEC EDGAR + OpenFIGI), concurrent with narratives…");
  // 240s caps a runaway: OpenFIGI's unauth tier throttles each batch ~2.5s
  // (~125s with OPENFIGI_MAX_BATCHES_UNAUTH=50) and the slowest EDGAR firm can
  // burn its full per-firm budget on top — 185s observed in the wild.
  const F13_TIMEOUT_MS = 240_000;
  const f13Empty = { perFirm: {}, overallTopBought: [], overallTopSold: [] };
  let f13TimeoutHandle = null;
  const f13TimeoutPromise = new Promise((resolve) => {
    f13TimeoutHandle = setTimeout(() => {
      console.log(`  ⚠ buildPerFirm13FHoldings exceeded ${F13_TIMEOUT_MS / 1000}s — keeping baseline.`);
      resolve(f13Empty);
    }, F13_TIMEOUT_MS);
  });
  const f13WorkPromise = buildPerFirm13FHoldings().catch((err) => {
    console.log(`  ⚠ buildPerFirm13FHoldings failed: ${err?.message || err}`);
    return f13Empty;
  });
  // Macro releases are fetched EARLY (they used to live in the calendar batch
  // far below) so a day-of print — CPI at 8:30 ET, actual vs consensus, with
  // ForexFactory's fast actual — reaches the narrative extractor and the
  // briefs in the SAME build instead of only the calendar tab. The window
  // starts a few days back so a Friday NFP still reads on Monday; the
  // calendar payload keeps its today-forward view via the filter below. The
  // FRED-cascade coupling with fetchEffectiveFedFundsRate is preserved: the
  // counter is module-level and the rate fetch still runs strictly after
  // this in the calendar section.
  const todayMs = Date.UTC(
    new Date().getUTCFullYear(),
    new Date().getUTCMonth(),
    new Date().getUTCDate(),
  );
  const cutoffMs = calendarCutoffMs(todayMs);
  const todayIsoEarly = new Date(todayMs).toISOString().slice(0, 10);
  console.log("Fetching macro releases (BLS primary · FRED fallback · ForexFactory consensus)…");
  const reportEventsAll = await fetchMacroReleases(todayMs - MACRO_RELEASE_LOOKBACK_DAYS * 86400000, cutoffMs);
  const reportEvents = reportEventsAll.filter((r) => String(r.date) >= todayIsoEarly);
  const macroReleaseReads = buildMacroReleaseReads(reportEventsAll, todayIsoEarly);
  console.log(`  · ${reportEvents.length} report rows (${macroReleaseReads.length} already printed in the last ${MACRO_RELEASE_LOOKBACK_DAYS}d)`);
  for (const r of macroReleaseReads) console.log(`    · ${r.line}`);
  const trends = await attachMarketNarratives(chains, previousHistory, macroReleaseReads);
  const symbols = Object.keys(chains).sort();
  const spots = Object.fromEntries(symbols.map((s) => [s, chains[s].spot]));
  // Market backdrop — compact per-index snapshot for the Execute now? card so
  // the entry-timing read can ask "is the broader tape with us or against
  // us?". Live moves are overlaid at runtime via /api/quote; the baked
  // priceMove1dPct is the fallback when the live fetch flakes or the market
  // is closed. Picks the broad-market ETFs (risk-on/off proxy), the semis
  // ETF (for tech/semis sector tilt), and UVXY (vol-spike proxy in lieu of
  // a direct ^VIX feed). All five are in TICKERS already so no extra fetch.
  const MARKET_BACKDROP_SYMBOLS = ["SPY", "QQQ", "IWM", "SMH", "UVXY"];
  const marketBackdrop = {};
  for (const sym of MARKET_BACKDROP_SYMBOLS) {
    const c = chains[sym];
    if (!c || !c.technicals) continue;
    const t = c.technicals;
    const vol = t.volume || {};
    marketBackdrop[sym] = {
      spot: c.spot ?? null,
      move1dPct: vol.priceMove1dPct ?? null,
      rsi: t.rsi ?? null,
      macdHist: t.macd?.hist ?? null,
      rvol: vol.rvol ?? null,
      s20: t.sr?.s20 ?? null,
      r20: t.sr?.r20 ?? null,
    };
  }
  // Next two FOMC dates — used by the Execute card to defer entries when
  // a rate decision is ≤2 sessions away (Powell pressers routinely whipsaw
  // multi-percent intraday). Baseline list is good enough for this purpose;
  // we don't need the live-fetched merge until the calendar pipeline runs.
  const todayIsoForFomc = new Date().toISOString().slice(0, 10);
  const nextFomcDates = FOMC_MEETINGS_BASELINE
    .map((m) => m.date)
    .filter((d) => d >= todayIsoForFomc)
    .sort()
    .slice(0, 2);
  const builtAtIso = new Date().toISOString();
  const html = renderHtml({
    symbols,
    builtAt: nyTimestamp(),
    builtAtIso,
    narratives: trends.narratives,
    sectorOverviews: trends.sectorOverviews || {},
    recentlyEnded: trends.recentlyEnded,
    macroHeadlines: trends.macroHeadlines || [],
    unusual,
    spots,
    fearGreed,
    macro: macroBackdrop,
    volumeFlags,
    marketBackdrop,
    nextFomcDates,
    oi: oiTracker,
    dataDir: DATA_DIR,
  });
  const css = renderStylesCss();
  const js = renderAppJs({ riskFreeRate });
  await mkdir(dirname(OUT), { recursive: true });
  await writeFile(OUT, html, "utf8");
  await writeFile(resolve(ROOT, "styles.css"), css, "utf8");
  await writeFile(resolve(ROOT, "app.js"), js, "utf8");
  const totalChainBytes = await writeChainFiles(chains, riskFreeRate?.rate ?? FALLBACK_RISK_FREE_RATE);
  // Persist the refreshed chart-pattern cache (read before the wipe, updated by
  // attachChartPatterns) so the next same-day build can reuse unchanged reads.
  // writeChainFiles just recreated data/, so this must come after it.
  await writeChartPatternCache(chartPatternCacheNext);
  // Same rule for the ticker-judgment cache (read before the wipe, updated by
  // attachTickerJudgments + attachAiContractGuidance above).
  await writeTickerJudgmentCache(tickerJudgmentCacheNext);
  // Persist macro to disk AFTER writeChainFiles — that call wipes data/
  // wholesale, so writing macro.json before it deletes our snapshot
  // immediately (confirmed in git history: chore: daily refresh 2026-05-25
  // committed a `deleted file` for data/macro.json). regen-static.mjs reads
  // this file directly, so without it the Bonds & USD live tile and the
  // home card go blank between full builds.
  if (macroBackdrop) {
    await writeFile(resolve(DATA_DIR, "macro.json"), JSON.stringify(macroBackdrop, null, 2), "utf8");
  }
  // Rolling EOD macro history. Always rewritten so prior days survive the
  // data/ wipe, even when today's fetch fails (we just don't upsert today).
  await writeMacroHistory(macroHistoryNext);
  console.log(`wrote data/${MACRO_HISTORY_FILE} — ${macroHistoryNext.entries.length} daily snapshots`);
  // Persist today's ^IRX so a future Yahoo flake can fall back to it.
  // We only refresh on a 'fresh' read — keeping a stale cache from
  // overwriting itself with the same stale data lets the age-out at
  // RFR_CACHE_MAX_DAYS work correctly.
  if (riskFreeRate?.source === "fresh" && Number.isFinite(riskFreeRate.rate)) {
    await writeRfrHistory({
      rate: riskFreeRate.rate,
      asOf: riskFreeRate.asOf,
      capturedAt: new Date().toISOString().slice(0, 10),
    });
  } else if (cachedRfr) {
    // Cache wasn't refreshed — re-persist the prior reading so it
    // survives writeChainFiles' wipe for tomorrow's build.
    await writeRfrHistory(cachedRfr);
  }
  const streaksInfo = await writeStreaksFile(chains, builtAtIso);
  console.log(`wrote data/streaks.json — ${streaksInfo.count} tickers, ${streaksInfo.bytes} bytes`);
  const heatmapInfo = await writeHeatmapFile(chains, builtAtIso, priorHeatmapEod, priorHeatmapRotation);
  console.log(`wrote data/heatmap.json — ${heatmapInfo.count} tickers, ${heatmapInfo.bytes} bytes${heatmapInfo.eodPreserved ? ` (carried over EOD recap from ${priorHeatmapEod.date})` : ""}${heatmapInfo.rotationAlerts ? ` (${heatmapInfo.rotationAlerts} sector-rotation alert${heatmapInfo.rotationAlerts === 1 ? "" : "s"})` : ""}`);
  const correlationsInfo = await writeCorrelationsFile(chains, globalMarkets, builtAtIso, priorCorrelations);
  console.log(`wrote data/correlations.json — ${correlationsInfo.symbols} markets, ${correlationsInfo.mapped} mapped tickers, ${correlationsInfo.bytes} bytes${correlationsInfo.stale ? " [stale — kept last-good]" : ""}`);
  // AI CapEx (Mag 7 aggregate, from SEC XBRL) + capital-raises feed (news scan
  // during the judgments pass, SEC-enriched). Both are SEC/news-sourced and
  // carry last-good forward on a fetch miss (graceful). cikMap is the build's
  // cached SEC ticker→CIK map (already loaded above).
  try {
    const cikMap = await fetchCikMap();
    const aiCapexInfo = await writeAiCapexFile(cikMap, chains, builtAtIso, priorAiCapex);
    console.log(`wrote data/ai-capex.json — ${aiCapexInfo.count} companies, ${aiCapexInfo.bytes} bytes${aiCapexInfo.stale ? " [stale — kept last-good]" : ""}${aiCapexInfo.missing.length ? ` (no data: ${aiCapexInfo.missing.join(",")})` : ""}`);
    const capRaisesInfo = await writeCapitalRaisesFile(cikMap, chains, builtAtIso, priorCapitalRaises);
    console.log(`wrote data/capital-raises.json — ${capRaisesInfo.count} events, ${capRaisesInfo.bytes} bytes${capRaisesInfo.stale ? " [stale — kept last-good]" : ""}`);
  } catch (err) {
    console.log(`  ⚠ AI CapEx / capital-raises step failed (non-fatal): ${err.message}`);
  }
  // RAM price tracker (TrendForce/DRAMeXchange spot + WhereIsMyRam retail) —
  // carries last-good forward on a fetch/parse miss (graceful).
  try {
    const ramInfo = await writeRamPricesFile(builtAtIso, priorRamPrices);
    console.log(`wrote data/ram-prices.json — ${ramInfo.spotItems} spot items${ramInfo.spotStale ? " [stale]" : ""}, ${ramInfo.retailCats} retail categories${ramInfo.retailStale ? " [stale]" : ""}, ${ramInfo.bytes} bytes`);
  } catch (err) {
    console.log(`  ⚠ RAM-prices step failed (non-fatal): ${err.message}`);
  }
  await writeTrendFiles({
    narratives: trends.narratives,
    sectorOverviews: trends.sectorOverviews || {},
    recentlyEnded: trends.recentlyEnded,
    macroHeadlines: trends.macroHeadlines || [],
    history: trends.history,
    builtAtIso,
  });
  if (unusual) {
    await writeFile(resolve(DATA_DIR, UNUSUAL_FILE), JSON.stringify(unusual), "utf8");
  }
  if (unusualHistory) {
    await writeFile(resolve(DATA_DIR, UNUSUAL_HISTORY_FILE), JSON.stringify(unusualHistory), "utf8");
  }
  if (unusualLog) {
    await writeFile(resolve(DATA_DIR, UNUSUAL_LOG_FILE), JSON.stringify(unusualLog), "utf8");
  }
  if (volumeFlags) {
    await writeFile(resolve(DATA_DIR, VOLUME_FLAGS_FILE), JSON.stringify(volumeFlags), "utf8");
  }
  if (volumeHistory) {
    await writeFile(resolve(DATA_DIR, VOLUME_HISTORY_FILE), JSON.stringify(volumeHistory), "utf8");
  }
  if (oiTracker) {
    await writeFile(resolve(DATA_DIR, OI_TRACKER_FILE), JSON.stringify(oiTracker), "utf8");
  }
  if (oiHistory) {
    await writeFile(resolve(DATA_DIR, OI_HISTORY_FILE), JSON.stringify(oiHistory), "utf8");
  }
  const ivHistoryBytes = await writeIvHistory(ivHistory);
  if (ivHistory.size) {
    console.log(`wrote data/iv-history/ — ${ivHistory.size} tickers, ${ivHistoryBytes} bytes total`);
  }
  // Trending IV — derived screen over the just-flushed iv-history (current
  // ATM ~30d IV vs each name's own history + short-term direction). Purely
  // deterministic and rebuilt every bake; non-fatal on failure (the tab shows
  // its empty state until the next successful bake). The payload is kept for
  // the market brief below — its IV-tracker section notes the actionable
  // (tiered) flags.
  let ivTrendingForBrief = null;
  try {
    const { payload: ivTrending, bytes: ivTrendingBytes } = await writeIvTrendingFile(ivHistory, chains);
    ivTrendingForBrief = ivTrending;
    console.log(`wrote data/${IV_TRENDING_FILE} — ${ivTrending.tickers.length} ranked, ${ivTrending.trendingCount} trending, ${ivTrendingBytes} bytes`);
  } catch (err) {
    console.log(`Trending-IV write failed (non-fatal): ${err.message}`);
  }
  // Earnings-history store back into the freshly-recreated data/ (pre-read +
  // updated above, before the wipe).
  const earningsHxBytes = await writeEarningsEventsHistory(earningsHxStore);
  console.log(`wrote data/${EARNINGS_HISTORY_FILE} — ${Object.keys(earningsHxStore.tickers).length} tickers, ${earningsHxBytes} bytes`);
  // Fear & Greed: write today's snapshot + the appended per-component
  // history back into the freshly-recreated data/ dir. We always persist
  // history (even with no fresh snapshot) so prior days survive.
  if (fearGreed) {
    await writeFearGreedFile(fearGreed);
    console.log(`wrote data/${FNG_FILE} — score ${fearGreed.score} (${fearGreed.rating})${fearGreed.stale ? " [stale]" : ""}`);
  }
  const todayIsoForFng = new Date().toISOString().slice(0, 10);
  const fngHistoryNext = fearGreed && !fearGreed.stale
    ? appendFearGreedHistory(fngHistoryPrev, fearGreed, todayIsoForFng)
    : fngHistoryPrev;
  await writeFearGreedHistory(fngHistoryNext);
  console.log(`wrote data/${FNG_HISTORY_FILE} — ${fngHistoryNext.snapshots.length} daily snapshots`);
  // Calendar extras: FOMC schedule, current effective Fed funds rate, and a
  // fresh CME FedWatch snapshot. (Structured macro releases were already
  // fetched up top, before the narrative pass, so the day's prints could
  // feed the narratives — reportEvents is reused here.) FedWatch history is
  // append-only — today's snapshot lands beside any prior days so the UI
  // can pick Now / 1d / 1w / 1m buckets.
  const calDays = Math.round((cutoffMs - todayMs) / 86400000);
  // Distinct dates curated tickers actually report on, across the full window —
  // the only dates the Nasdaq AM/PM session fetch needs. Avoids walking every
  // weekday of a months-long window (see fetchNasdaqEarningsSessions).
  const earnSessionDates = Array.from(new Set(
    upcomingEarningsList(chains, new Date(todayMs).toISOString().slice(0, 10), calDays).map((e) => e.date),
  ));
  // These calendar sources hit DIFFERENT hosts — NY Fed EFFR (Fed Funds
  // rate), the Fed's FOMC calendar page, and Nasdaq (earnings sessions) —
  // with no data dependency on one another, so fetch them concurrently. This
  // overlaps the independent round trips without raising the request rate to
  // ANY single host (one call each), and each already degrades gracefully on
  // its own.
  //
  // ONE subtlety preserved: macro releases AND the Fed-rate fetch both fall
  // back to FRED (fetchFredSeries), which shares the module-level
  // _fredFirstAttemptFailures cascade counter — deliberately scoped (see
  // ~line 4369) so a FRED cascade in the macro fetch also short-circuits the
  // Fed-rate fetch. The macro-release fetch now runs much earlier in main()
  // (before the narrative pass), still STRICTLY BEFORE this rate fetch, so
  // the counter semantics are identical to the original macro → rate order.
  // The FedWatch/CME ZQ source depends on fedRate + the FOMC schedule, so it
  // stays sequential after this batch resolves.
  console.log("Fetching calendar sources (NY Fed EFFR · FOMC schedule · Nasdaq earnings) in parallel…");
  const [fedRate, liveFomc, sessionMap] = await Promise.all([
    fetchEffectiveFedFundsRate(),
    fetchFomcSchedule(),
    fetchNasdaqEarningsSessions(todayMs, calDays, earnSessionDates),
  ]);
  if (fedRate) console.log(`  · Fed Funds ${fedRate.rate}% as of ${fedRate.asOf}`);
  // FedWatch history was read BEFORE writeChainFiles wiped data/. Start
  // from that pre-wipe snapshot so the lastKnownFedRate cache actually
  // serves as a fallback when NY Fed + FRED:DFF both flake today — the Fed only
  // moves rates every 6-8 weeks, so a 14-day-old anchor still produces
  // a defensible probability spread.
  const fedwatchHistory = fedwatchHistoryPrev || { meetings: {} };
  if (!fedwatchHistory.meetings) fedwatchHistory.meetings = {};
  let effectiveFedRate = fedRate;
  if (!effectiveFedRate && fedwatchHistory.lastKnownFedRate) {
    const last = fedwatchHistory.lastKnownFedRate;
    const lastMs = Date.parse(last.capturedAt || last.asOf || "");
    const ageDays = Number.isFinite(lastMs) ? (Date.now() - lastMs) / 86400000 : Infinity;
    if (ageDays <= 14 && Number.isFinite(last.rate)) {
      effectiveFedRate = { rate: last.rate, asOf: last.asOf, source: "Fed Funds (cached)" };
      console.log(`  · using cached Fed Funds rate ${last.rate}% from ${last.capturedAt || last.asOf} (${ageDays.toFixed(1)}d old)`);
    }
  }
  // liveFomc was fetched in the parallel batch above (Fed calendar HTML).
  // Merge with the multi-year baseline; a network failure there yields an
  // empty live list → falls back cleanly to the baseline.
  const allFomcMeetings = mergeFomcMeetings(liveFomc, FOMC_MEETINGS_BASELINE);
  console.log(`  · ${allFomcMeetings.length} FOMC dates (baseline ${FOMC_MEETINGS_BASELINE.length}, live ${liveFomc.length})`);
  console.log("Computing FedWatch probabilities from ZQ Fed Funds Futures…");
  const upcomingMeetings = allFomcMeetings.filter((m) => {
    const ms = Date.UTC(Number(m.date.slice(0,4)), Number(m.date.slice(5,7))-1, Number(m.date.slice(8,10)));
    return ms >= todayMs;
  });
  const todayIso = new Date(todayMs).toISOString().slice(0, 10);
  // Compute hike/hold/cut probabilities from the front-month ZQ contract
  // for each upcoming meeting. Requires the current effective rate as a
  // pre-meeting anchor — without it we can't separate pre/post-meeting
  // averages from the implied month-average rate.
  const currentRateNum = effectiveFedRate?.rate;
  // Persist today's Fed rate so a future outage can still anchor
  // FedWatch from a recent observation. Only update when we got a fresh
  // reading (NY Fed or FRED), not when we fell back to the cached value.
  if (fedRate && Number.isFinite(fedRate.rate)) {
    fedwatchHistory.lastKnownFedRate = {
      rate: fedRate.rate,
      asOf: fedRate.asOf,
      capturedAt: todayIso,
    };
  }
  // Anchor the probability math to the FOMC's target-range MIDPOINT (e.g.
  // 3.625% for a 3.50–3.75 band), not the effective rate itself — that's the
  // base CME FedWatch measures hike/hold/cut against, so our numbers line up
  // with theirs. EFFR usually sits a few bp below the midpoint inside the band.
  const anchorRate = fedTargetRangeMidpoint(currentRateNum);
  const snapshot = await fetchFedwatchSnapshot(upcomingMeetings, anchorRate);
  let snapshotCount = 0;
  for (const [meetingDate, buckets] of Object.entries(snapshot)) {
    if (!buckets?.now) continue;
    if (!fedwatchHistory.meetings[meetingDate]) fedwatchHistory.meetings[meetingDate] = {};
    fedwatchHistory.meetings[meetingDate][todayIso] = buckets.now;
    snapshotCount++;
  }
  pruneFedwatchHistory(fedwatchHistory, todayIso);
  await writeFedwatchHistory(fedwatchHistory);
  console.log(`  · ${snapshotCount} meeting snapshots (history: ${Object.keys(fedwatchHistory.meetings).length} meetings tracked)`);
  // For each upcoming meeting, ship the four lookback buckets the UI
  // expects (Now / 1d / 1w / 1m). The buckets come straight from the
  // ZQ historical chart (one fetch per contract covers all four
  // lookbacks). If the historical fetch flaked, fall back to the
  // history-walk so the widget still renders something.
  const fedwatch = {};
  for (const m of upcomingMeetings) {
    const fresh = snapshot[m.date];
    if (fresh && (fresh.now || fresh.day || fresh.week || fresh.month)) {
      fedwatch[m.date] = fresh;
    } else {
      fedwatch[m.date] = pickFedwatchBuckets(fedwatchHistory, m.date, todayIso);
    }
  }
  // Earnings AM/PM session: Nasdaq's calendar API returns
  // time-pre-market / time-after-hours / time-not-supplied per ticker,
  // which is far more reliable than Yahoo's earnings-timestamp hour
  // (Yahoo returns 00:00 UTC for many confirmed earnings, which falls
  // back to TBD). Builds a SYM|YYYY-MM-DD → AM/PM/TBD map.
  // sessionMap (Nasdaq earnings AM/PM) was fetched in the parallel batch above.
  console.log(`  · ${sessionMap.size} earnings session entries`);
  // Prediction-market overlay (Kalshi + Polymarket) — a market-based cross-check
  // on the ZQ-futures FedWatch numbers above + a best-effort odds reading beside
  // macro releases. Free public reads, no key; degrades to nothing if a host flakes.
  let predictionMarkets = { fomc: {}, reports: {}, earnings: {} };
  try {
    console.log("Fetching prediction markets (Kalshi + Polymarket)…");
    const earningsEvents = upcomingEarningsList(chains, todayIso);
    predictionMarkets = await fetchPredictionMarkets(upcomingMeetings, reportEvents, earningsEvents);
  } catch (err) {
    console.log(`  ⚠ prediction markets skipped: ${err?.message || err}`);
  }
  // Roll today's FOMC odds into the rolling history (pre-read before the wipe),
  // write it back, then attach the Δ/sparkline trend onto the odds the calendar
  // ships. Best-effort — a failure here just means no trend this build.
  try {
    const predictionHistory = predictionHistoryPrev && predictionHistoryPrev.meetings ? predictionHistoryPrev : { meetings: {} };
    appendPredictionHistory(predictionHistory, predictionMarkets.fomc, todayIso);
    prunePredictionHistory(predictionHistory, todayIso);
    await writePredictionHistory(predictionHistory);
    predictionMarkets.fomc = attachPredictionTrends(predictionMarkets.fomc, predictionHistory, todayIso);
  } catch (err) {
    console.log(`  ⚠ prediction history skipped: ${err?.message || err}`);
  }
  // Macro event-risk signal (#5) for the entry-timing gate, derived from the
  // prediction-market odds and read by computeEntryTiming via macroBackdrop.
  // Picks + grades are scored AFTER this, so the defer applies this build. Not
  // persisted to macro.json — it's a picks-internal, this-build-only signal.
  if (macroBackdrop) {
    macroBackdrop.eventRisk = computeMacroEventRisk(predictionMarkets, upcomingMeetings, reportEvents, todayIso);
    if (macroBackdrop.eventRisk && macroBackdrop.eventRisk.active) {
      const er = macroBackdrop.eventRisk;
      console.log(`  · macro event-risk: ${er.label} in ${er.daysOut}d (top ~${Math.round((er.topProb > 1.5 ? er.topProb / 100 : er.topProb) * 100)}%) — entries deferred`);
    }
    // Market-tape (cross-asset macro regime, PICKS_MACRO_REGIME) — the reworked
    // gauge that RESETS every build from the live factors: the overall-market
    // Indexes axis (SPY+QQQ), VIX, long yields, the dollar, the Fed path / FOMC,
    // a commodity / geopolitical-shock axis, a geopolitical-NEWS axis (war /
    // tariffs / Iran / real-world events), inflation/labor, Fear & Greed, and the
    // overnight global tape. Threaded into scoring (the risk-on/off tilt + the
    // tactical-put bar) and the roster (de-grossing). No cross-build persistence —
    // the chip reflects THIS build's tape. A picks-internal, this-build-only
    // signal (not persisted to macro.json).
    // Indexes axis input — SPY/QQQ moves read off the just-fetched chains.
    macroBackdrop.indexes = buildIndexAxisInput(chains);
    // Universe-breadth + put/call axes — computed off the just-fetched chains
    // (SMAs / 52w extremes / option OI+volume). Not persisted to macro.json (they
    // ride on the in-memory chains); regen-picks recomputes them the same way.
    macroBackdrop.breadth = buildBreadthAxisInput(chains);
    macroBackdrop.putCall = buildPutCallAxisInput(chains);
    macroBackdrop.rotation = buildRotationAxisInput(chains);
    if (macroBackdrop.breadth) console.log(`  · breadth: ${macroBackdrop.breadth.pctAbove200 != null ? macroBackdrop.breadth.pctAbove200.toFixed(0) + "% >200DMA" : "—"}, ${macroBackdrop.breadth.pctAbove50 != null ? macroBackdrop.breadth.pctAbove50.toFixed(0) + "% >50DMA" : "—"}, NH−NL ${macroBackdrop.breadth.nhnl != null ? macroBackdrop.breadth.nhnl : "—"} (n=${macroBackdrop.breadth.n})`);
    if (macroBackdrop.putCall) console.log(`  · put/call: OI ${macroBackdrop.putCall.oiRatio}, vol ${macroBackdrop.putCall.volRatio} (${macroBackdrop.putCall.names} names)`);
    if (macroBackdrop.rotation) console.log(`  · rotation: offense ${macroBackdrop.rotation.offense >= 0 ? "+" : ""}${macroBackdrop.rotation.offense}% − defense ${macroBackdrop.rotation.defense >= 0 ? "+" : ""}${macroBackdrop.rotation.defense}% = ${macroBackdrop.rotation.spread >= 0 ? "+" : ""}${macroBackdrop.rotation.spread}pp`);
    // Fold the overnight cross-asset sweep into the regime as the global-tape
    // axis (PICKS_MACRO_GLOBAL) — the same markets the Top Picks barometer shows.
    macroBackdrop.crossAsset = deriveGlobalTapeAxis(correlationsInfo?.payload?.markets || null);
    macroBackdrop.macroRegime = computeMacroRegime(macroBackdrop, fedwatchHistory, trends.narratives, fearGreed, trends.macroHeadlines);
    if (macroBackdrop.macroRegime && macroBackdrop.macroRegime.state !== "neutral") {
      const m = macroBackdrop.macroRegime;
      console.log(`  · market tape: ${m.state} (stress ${m.stress}, ${m.riskOffAxes} risk-off axes)${m.drivers.length ? ` — ${m.drivers.join(", ")}` : ""}`);
    }
  }
  const calendarInfo = await writeCalendarFile(chains, trends.macroHeadlines || [], builtAtIso, {
    reportEvents,
    fomcMeetings: upcomingMeetings,
    predictionMarkets,
    // Use effectiveFedRate (not fedRate) so the widget shows the same
    // value the FedWatch math is actually anchored to — when FRED:DFF
    // fails today we fall back to a cached reading (up to 14d old), and
    // the UI now renders a 'Cached · Xd' tag courtesy of the source field.
    fedRate: effectiveFedRate || fedRate,
    fedwatch,
    sessionMap,
    priorCalendar,
  });
  console.log(`wrote data/calendar.json — ${calendarInfo.count} events (through ${new Date(cutoffMs).toISOString().slice(0, 10)}), ${calendarInfo.bytes} bytes`);
  // Top picks: rank tickers by fused signal score and write data/picks.json.
  // Uses chains[sym]._bars which is still attached in memory (writeChainFiles
  // destructured it out of the serialized payload but never deleted it).
  // Scanner-data extras for the scoring pipeline: the OI tracker + the rolling
  // flow log (both scanner-owned, pre-read before the wipe) and the overnight
  // correlations sweep (tonight's fresh payload, falling back to the pre-wipe
  // snapshot if the foreign sweep came back too thin to write).
  const scannerExtras = {
    oiTracker,
    flowLog: unusualLog,
    correlations: correlationsInfo?.payload || priorCorrelations,
    // §9.6 IC bridge — per-signal forward IC from the prior accuracy stats, so the
    // cross-sectional weights can lean toward signals that have actually predicted.
    // No-op until gate-era outcomes accumulate (today: bySignal carries no IC).
    signalIc: buildSignalIcMap(picksAccuracyPrev?.stats?.bySignal),
  };
  const picksInfo = await writeTopPicksFile(chains, trends.narratives, builtAtIso, unusual, macroBackdrop, picksPrev, volumeFlags, riskFreeRate?.rate ?? FALLBACK_RISK_FREE_RATE, picksAccuracyPrev?.closed ?? null, gradesHistoryPrev?.latest ?? null, scannerExtras, picksAccuracyPrev?.open ?? null, true, thesisProseCachePrev, streaksInfo.map);
  // Persist the thesis-prose cache now that data/ has been recreated.
  await writePickThesisCache(picksInfo?.thesisProseCache || thesisProseCachePrev || {});
  console.log(`wrote data/picks.json — top ${picksInfo.count} picks, ${picksInfo.bytes} bytes`);
  // Grade index for every tracked ticker (powers the Top Picks tab's grade-any-
  // ticker search). Same 4-pillar scoring as the picks above; full breakdown
  // for names that don't clear the actionable threshold.
  // Build the grade index once and reuse it for the grades file, the grade-change
  // history diff, and the picks-accuracy checkpoint scores (avoids re-scoring).
  const gradesIndex = buildGradesIndex(chains, trends.narratives, streaksInfo.map, unusual, macroBackdrop, volumeFlags, { priorGrades: gradesHistoryPrev?.latest ?? null, priorClosed: picksAccuracyPrev?.closed ?? null, ...scannerExtras });
  const gradesInfo = await writeGradesFile(chains, trends.narratives, builtAtIso, unusual, macroBackdrop, volumeFlags, gradesIndex);
  console.log(`wrote data/grades.json — ${gradesInfo.count} tickers, ${gradesInfo.bytes} bytes`);
  // Daily grade snapshot (universe-IC substrate): upsert today's ET row with every
  // name's total, so scripts/diagnose-grade-ic.mjs can measure the grade's forward
  // IC on the whole universe instead of the ~5-per-build enrolled roster.
  try {
    const gd = await writeGradesDaily(appendGradesDaily(gradesDailyPrev, gradesIndex, builtAtIso));
    console.log(`wrote data/grades-daily.json — ${gd.days} day snapshot(s), ${gd.bytes} bytes`);
  } catch (err) {
    console.warn(`[grades] daily snapshot skipped — ${String(err?.message || err).split("\n")[0]}`);
  }
  // Daily market-regime timeline (Top Picks "risk-on / risk-off history"
  // calendar): upsert today's ET row from the macro-regime gauge that drove this
  // build's roster + the day's call/put lean (from writeTopPicksFile's return).
  // Pre-read above (regimeHistoryPrev) before the wipe, same as the grade
  // histories; carries forward unchanged when there's no macro backdrop.
  try {
    const regimeNext = appendRegimeHistory(regimeHistoryPrev, macroBackdrop?.macroRegime || null, picksInfo?.lean || null, builtAtIso);
    const rh = await writeRegimeHistory(regimeNext);
    console.log(`wrote data/${REGIME_HISTORY_FILE} — ${rh.days} day snapshot(s), ${rh.bytes} bytes`);
  } catch (err) {
    console.warn(`[regime] history skipped — ${String(err?.message || err).split("\n")[0]}`);
  }
  // Market analysis payload (data/market-analysis.json, premium but NOT
  // role-restricted): the same macroRegime object that rides picks.json's
  // rosterMeta, split out so the Market analysis tab (market tape / barometer /
  // regime widgets) works for every premium member — picks.json itself is
  // role-restricted to the Top Picks role (`tp`). Rebuilt every build from the
  // in-memory backdrop; no cross-build accumulation, so no pre-wipe read.
  try {
    const maJson = JSON.stringify({ builtAtIso, macroRegime: macroBackdrop?.macroRegime || null });
    await writeFile(resolve(DATA_DIR, "market-analysis.json"), maJson, "utf8");
    console.log(`wrote data/market-analysis.json — market tape, ${maJson.length} bytes`);
  } catch (err) {
    console.warn(`[market] analysis payload skipped — ${String(err?.message || err).split("\n")[0]}`);
  }
  // Daily index-close calendar (the top-level "Index calendar" tab): upsert today's
  // SPY/QQQ/IWM row and, on the first run, backfill ~1yr of history from the bars
  // already in memory (chains[]._bars survive writeChainFiles, so this runs after
  // the wipe). Pre-read above (indexCalendarPrev) before the wipe, same as the
  // grade/regime histories; carries forward unchanged when bars are missing.
  try {
    // VXUS (total international) + ^VIX (volatility) aren't chain tickers, so
    // fetch their daily bars here ([{c,t}] from the same helper the overnight
    // sweep uses) and pass them as extraBars. A failed fetch just leaves that
    // column empty for the day — graceful, carried forward like the rest.
    const indexCalExtra = {};
    for (const sym of INDEX_CALENDAR_EXTRA_SYMBOLS) {
      try { indexCalExtra[sym] = (await fetchGlobalMarketBars(sym)).bars; }
      catch (err) { console.log(`    ⚠ index-cal ${sym} bars fetch failed: ${err.message}`); }
    }
    const ic = await writeIndexCalendar(appendIndexCalendar(indexCalendarPrev, chains, builtAtIso, indexCalExtra));
    console.log(`wrote data/${INDEX_CALENDAR_FILE} — ${ic.days} session row(s), ${ic.bytes} bytes`);
  } catch (err) {
    console.warn(`[index-cal] calendar skipped — ${String(err?.message || err).split("\n")[0]}`);
  }
  // Grade-change log: diff the fresh index against the pre-wipe snapshot.
  try {
    const gradesHistoryNext = diffGradesHistory(gradesHistoryPrev, gradesIndex, builtAtIso);
    await writeGradesHistory(gradesHistoryNext);
    console.log(`wrote data/${GRADES_HISTORY_FILE} — ${gradesHistoryNext.changes.length} change events`);
  } catch (err) {
    console.warn(`[grades] history skipped — ${String(err?.message || err).split("\n")[0]}`);
  }
  // Picks churn log: which names crossed the actionable conviction bar this build
  // and why. Detected against the SAME pre-wipe grade snapshot the grade-change
  // log uses (gradesHistoryPrev.latest), so it's immune to the pre-bell pick
  // collapse. Deterministic detection first, then an optional AI one-liner per
  // new event (self-skips without GEMINI_API_KEY), then append + prune + write.
  // Hoisted so the market briefs below can surface today's entered/exited names.
  let churnEventsForBrief = [];
  try {
    const churnEvents = buildPicksChanges(gradesHistoryPrev.latest, gradesIndex, builtAtIso, picksChangesPrev);
    churnEventsForBrief = churnEvents;
    const picksChangesNext = appendPicksChanges(picksChangesPrev, churnEvents, builtAtIso, gradeTradeCut(gradesIndex));
    await writePicksChanges(picksChangesNext);
    const entered = churnEvents.filter((e) => e.event === "entered").length;
    const exited = churnEvents.length - entered;
    console.log(`wrote data/${PICKS_CHANGES_FILE} — ${entered} in, ${exited} out this build (${picksChangesNext.changes.length} logged)`);
  } catch (err) {
    console.warn(`[picks] churn log skipped — ${String(err?.message || err).split("\n")[0]}`);
  }
  // Top-10 roster snapshot: the current 10-name list with each pick's in/held/new
  // status, prior→current pillar deltas, the names that dropped OUT (paired to the
  // entrant that took their slot), and a per-pick upgrade/downgrade FORECAST.
  // Reads the just-written picks.json (so it reflects the stale-reused set on a
  // pre-bell run) and diffs against the prior visible top-N (picksPrev) plus the
  // pre-wipe whole-universe grade snapshot (gradesHistoryPrev.latest, which keeps
  // status pre-bell-collapse immune). Deterministic forecast first, then an
  // optional AI gloss (self-skips without GEMINI_API_KEY).
  try {
    let currentPicksPayload = null;
    try { currentPicksPayload = JSON.parse(await readFile(resolve(DATA_DIR, PICKS_FILE), "utf8")); } catch {}
    const rosterPayload = buildPicksRoster(
      currentPicksPayload?.picks || [],
      picksPrev?.picks || null,
      gradesHistoryPrev.latest,
      gradesIndex,
      builtAtIso,
      !!currentPicksPayload?.stale,
    );
    await writePicksRoster(rosterPayload);
    console.log(`wrote data/${PICKS_ROSTER_FILE} — ${rosterPayload.count} in roster, ${rosterPayload.exited.length} out, ${rosterPayload.swaps.length} swap(s)`);
  } catch (err) {
    console.warn(`[picks] roster snapshot skipped — ${String(err?.message || err).split("\n")[0]}`);
  }
  // Pick accuracy tracker: enroll today's picks, mark open ones to market, and
  // resolve any that hit take-profit / cut / expiry. Reads the picks.json we
  // just wrote; uses chains[sym].spot for the marks. Carries the prior tracker
  // state forward via picksAccuracyPrev (snapshotted before writeChainFiles
  // wiped data/). Degrades to a no-op on a first run / missing files.
  try {
    const acc = await updatePicksAccuracyFile(chains, builtAtIso, picksAccuracyPrev, gradesIndex);
    console.log(`wrote data/${PICKS_ACCURACY_FILE} — ${acc.open} open, ${acc.closed} closed${acc.winRate != null ? `, ${(acc.winRate * 100).toFixed(0)}% win rate` : ""}`);
  } catch (err) {
    console.warn(`[picks] accuracy tracker skipped — ${String(err?.message || err).split("\n")[0]}`);
  }
  // Market brief (rolling hourly digest) — re-minted at most once per ET hour,
  // so every hourly bake ships a fresh read and a same-hour re-run carries the
  // existing one forward. Built from the data already in memory: overnight
  // correlations, the session's breadth + movers, unusual flow, macro levels,
  // Fear & Greed, the calendar, and the top picks.
  // Runs BEFORE writeAiUsageState so the brief's token usage is persisted.
  try {
    const briefTodayIso = etDateKey();
    let picksForBrief = [];
    try {
      const pj = JSON.parse(await readFile(resolve(DATA_DIR, PICKS_FILE), "utf8"));
      picksForBrief = Array.isArray(pj?.picks) ? pj.picks : [];
    } catch (_) { /* no picks.json yet — brief omits the picks block */ }
    // Pure rebuild of the correlations payload (no fetch — reuses the already-
    // fetched globalMarkets + chains bars) for the overnight signal block.
    const briefCorrelations = buildCorrelationsPayload(chains, globalMarkets, builtAtIso, priorCorrelations);
    const sess = (sym, date) => sessionMap.get(`${sym}|${date}`) || "TBD";
    const allEarn = upcomingEarningsList(chains, briefTodayIso, 14);
    const calForBrief = {
      todayEarnings: allEarn.filter((e) => e.date === briefTodayIso).map((e) => ({ sym: e.symbol, session: sess(e.symbol, e.date) })),
      upcomingEarn: allEarn.filter((e) => e.date > briefTodayIso).sort((a, b) => a.date.localeCompare(b.date)).slice(0, 6).map((e) => ({ sym: e.symbol, date: e.date, session: sess(e.symbol, e.date) })),
      todayReports: (reportEvents || []).filter((r) => String(r.date) === briefTodayIso).map((r) => ({ title: r.title, subtype: r.subtype || null, actual: r.actual ?? null, consensus: r.consensus ?? null, previous: r.previous ?? null })),
      upcomingReports: (reportEvents || []).filter((r) => String(r.date) > briefTodayIso).sort((a, b) => String(a.date).localeCompare(String(b.date))).slice(0, 5).map((r) => ({ title: r.title, date: r.date })),
      // Releases that already printed (today + trailing lookback), classified
      // actual-vs-consensus — feeds the brief's released-data block (a fresh
      // print reaches the next hourly mint by construction).
      releases: macroReleaseReads,
      nextFomc: upcomingMeetings && upcomingMeetings[0]
        ? { date: upcomingMeetings[0].date, daysOut: Math.max(0, Math.round((Date.parse(upcomingMeetings[0].date + "T00:00:00Z") - Date.parse(briefTodayIso + "T00:00:00Z")) / 86400000)) }
        : null,
    };
    const briefRes = await buildMarketBriefs({
      briefsPrev, builtAtIso, chains, fearGreed, macro: macroBackdrop,
      correlations: briefCorrelations, unusual, picks: picksForBrief, calendar: calForBrief,
      rfr: riskFreeRate?.rate ?? FALLBACK_RISK_FREE_RATE, picksChanges: churnEventsForBrief,
      // The same filtered press/wire slate the narrative engine just read —
      // the brief's tape-driver input (fetched fresh by this bake).
      headlines: trends.macroHeadlines || [],
      // The just-written Trending-IV payload — the brief's IV-tracker section
      // (actionable tiered flags only).
      ivTrending: ivTrendingForBrief,
    });
    console.log(`wrote data/${BRIEFS_FILE} — ${briefRes.current ? `${briefRes.kind} brief${briefRes.generated ? " (freshly generated)" : " (carried forward)"}` : "no brief yet"}`);
  } catch (err) {
    console.warn(`[briefs] skipped — ${String(err?.message || err).split("\n")[0]}`);
  }
  // Persist AI usage now (rather than at the very end) so a hang/timeout in
  // the slow EDGAR fetch below can't leave data/ai-usage.json missing —
  // writeChainFiles wiped it, and we want to make sure it's written back
  // even when the 13F section degrades.
  await writeAiUsageState();
  // 13F summary: derives current quarter, filing window, top biggest
  // positions (ranked from live marketCap), and rotation themes (from the
  // narratives engine output) each build. Write a baseline file FIRST
  // (no live data, just the curated directory) so we always leave a usable
  // data/13f.json on disk; then attempt the EDGAR + OpenFIGI enrichment
  // under a hard timeout and overwrite when it succeeds. Without this
  // belt-and-suspenders setup, a slow OpenFIGI throttle (~2.5s × dozens of
  // batches per firm) can blow past the workflow budget and leave the
  // file deleted in the next commit.
  const baselineInfo = await write13FFile(chains, trends.narratives, builtAtIso, {});
  console.log(`wrote data/13f.json (baseline) — ${baselineInfo.positions} biggest positions, ${baselineInfo.bytes} bytes`);
  // The enrichment work + its 240s timeout race were kicked off concurrently up
  // near attachMarketNarratives so they overlapped the narratives/calendar/scoring
  // phases — by now it's usually already resolved. Await the race here, where the
  // result is consumed, and clear the timer when the real work won (otherwise the
  // unfired setTimeout would keep counting and later print a misleading
  // "exceeded 240s" warning). buildPerFirm13FHoldings returns
  // { perFirm, overallTopBought, overallTopSold }.
  const perFirmResult = await Promise.race([f13WorkPromise, f13TimeoutPromise]);
  clearTimeout(f13TimeoutHandle);
  const perFirmMap = perFirmResult.perFirm || {};
  const realFirms = Object.values(perFirmMap)
    .filter((v) => v && ((v.topBought && v.topBought.length) || (v.topSold && v.topSold.length)))
    .length;
  const totalFirms = Object.keys(perFirmMap).length;
  console.log(`  · ${realFirms}/${totalFirms} firms returned QoQ deltas (overall: ${perFirmResult.overallTopBought.length} buys / ${perFirmResult.overallTopSold.length} sells)`);
  if (realFirms > 0) {
    const f13Info = await write13FFile(chains, trends.narratives, builtAtIso, perFirmResult);
    console.log(`wrote data/13f.json (enriched) — ${f13Info.positions} biggest positions, ${f13Info.bytes} bytes`);
  } else {
    console.log("keeping baseline data/13f.json — EDGAR returned no usable holdings.");
  }
  console.log(
    `wrote ${OUT} (${(html.length / 1024).toFixed(1)} KB) + styles.css (${(css.length / 1024).toFixed(1)} KB) + app.js (${(js.length / 1024).toFixed(1)} KB) + ${symbols.length} chain files (${(totalChainBytes / 1024).toFixed(1)} KB total) + trends (${trends.narratives.length} active, ${trends.history.length}-day history)`,
  );
  logAiUsageSummary();
  await writeAiHealthReport();
}

async function writeTrendFiles({ narratives, sectorOverviews, recentlyEnded, macroHeadlines, history, builtAtIso }) {
  // writeChainFiles wiped data/ a moment ago, so write into the freshly
  // recreated directory.
  const current = JSON.stringify({ builtAtIso, narratives, sectorOverviews: sectorOverviews || {}, recentlyEnded, macroHeadlines });
  await writeFile(resolve(DATA_DIR, TRENDS_FILE), current, "utf8");
  const archive = JSON.stringify({ builtAtIso, days: NARRATIVE_HISTORY_DAYS, snapshots: history });
  await writeFile(resolve(DATA_DIR, TRENDS_HISTORY_FILE), archive, "utf8");
}

// Only auto-run the full data build when invoked as the entry point. This lets
// sibling tooling import renderStylesCss / renderAppJs to regenerate the
// static assets without triggering the Yahoo + Gemini calls main() makes.
const isEntryPoint = process.argv[1]
  && import.meta.url === pathToFileURL(process.argv[1]).href;
if (isEntryPoint) {
  main().catch((err) => {
    console.error(err);
    process.exit(1);
  });
}
